        ? instance.handleDisconnect?.bind(instance)
        : this.createRequestScopedEventHandler(
            instanceWrapper,
            moduleRef,
            moduleKey,
            'handleDisconnect',
            observableServer.server,
          ),
    );
  }"}]}
