49 public bindMessageHandlers(
50   socket: Socket,
51   handlers: MessageMappingProperties[],
52   transform: (data: any) => Observable<any>,
53 ) {
54   let disconnect$ = this.disconnectMap.get(socket);
55   if (!disconnect$) {
56     disconnect$ = fromEvent(socket, DISCONNECT_EVENT).pipe(share(), first());
57     this.disconnectMap.set(socket, disconnect$);
58   }
60   handlers.forEach(({ message, callback, isAckHandledManually }) => {
61     const source$ = fromEvent(socket, message).pipe(
62       mergeMap((payload: any) => {
63         const { data, ack } = this.mapPayload(payload);
64         // defer turns a sync throw into an error notification and catchError
65         // stops it from tearing down this event's stream, which would silence
66         // that event for the client. A handler whose error filter rethrows is
67         // an app bug, so the failure gets logged instead of dropped silently.
68         return defer(() => transform(callback(data, ack))).pipe(
69           filter((response: any) => !isNil(response)),
70           map((response: any) => [response, ack, isAckHandledManually]),
71           catchError(err => {
72             this.logger.error(err);
73             return EMPTY;
74           }),
75         );
76       }),
77       takeUntil(disconnect$),
78     );
79     source$.subscribe(([response, ack, isAckHandledManually]) => {
80       // socket.io's encoder walks the payload recursively, so a response
81       // echoing a client-controlled payload nested deep enough overflows the
82       // stack. A throw here escapes the subscriber, which RxJS rethrows
83       // asynchronously, killing the process.
84       try {
85         if (response.event) {
86           return socket.emit(response.event, response.data);
87         }
88         if (!isAckHandledManually && isFunction(ack)) {
89           ack(response);
90         }
91       } catch (err) {
92         this.logger.error(err);
93       }
94     });
95   });
96 }
